output_text:
[
  {
    "id": "no_carts_in_single_file_shelf_aisles",
    "text": "Shopping carts are forbidden in single-file shelf aisles where shelves border both sides.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "do_not_push_cart_into_single_file_aisle",
    "text": "Customers must not push a cart from an open aisle into a single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "pushCartIntoSingleFileAisle": {
          "pre": {
            "and": [
              "hasCart",
              {
                "or": [
                  "N",
                  "S",
                  "E",
                  "W"
                ]
              }
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "pushCartIntoSingleFileAisle"
    }
  },
  {
    "id": "retrieve_cart_after_parking",
    "text": "After parking a cart at the mouth of a narrow shelf aisle, the customer is obliged to retrieve a cart before continuing the trip.",
    "abstraction": {
      "state_properties": {
        "cartParkingMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "parkCartAtMouth": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT",
              "cartParkingMouth"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "retrieveCartAtMouth": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT",
              "cartParkingMouth"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCartAtMouth",
      "discharge": "retrieveCartAtMouth"
    }
  },
  {
    "id": "cartless_motion_only_in_handcarry_zone",
    "text": "Except for the entrance and the narrow-aisle hand-carry zone, customers should not move around the store without their cart.",
    "abstraction": {
      "state_properties": {
        "entranceZone": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        },
        "cartParkingMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "handCarryZone": {
          "or": [
            "singleFileShelfAisle",
            "cartParkingMouth"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "or": [
              "N",
              "S",
              "E",
              "W"
            ]
          },
          {
            "not": "hasCart"
          },
          {
            "not": "entranceZone"
          },
          {
            "not": "handCarryZone"
          }
        ]
      }
    }
  },
  {
    "id": "cart_required_for_lower_main_shelf_service",
    "text": "Interactions with lower main-aisle shelf positions must be done while holding the cart.",
    "abstraction": {
      "state_properties": {
        "lowerMainShelfServiceCell": {
          "and": [
            "adjShelf",
            "shelfN",
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "le": [
                "freeWidthV",
                2
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "lowerMainShelfServiceCell",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "upper_shelf_items_are_hand_only",
    "text": "Items in the single-file upper shelf aisles must be handled without a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "singleFileShelfAisle",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "one_way_wide_horizontal_aisles",
    "text": "Wide horizontal customer aisles are one-way, so westward travel in them is forbidden.",
    "abstraction": {
      "state_properties": {
        "wideHorizontalAisle": {
          "ge": [
            "freeWidthH",
            6
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "W",
          "wideHorizontalAisle"
        ]
      }
    }
  },
  {
    "id": "take_cart_before_leaving_entrance",
    "text": "A customer may not leave the entrance/cart area unless they have taken a cart.",
    "abstraction": {
      "state_properties": {
        "entranceArea": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        }
      },
      "events": {
        "leaveEntranceWithoutCart": {
          "pre": {
            "and": [
              "entranceArea",
              {
                "not": "hasCart"
              },
              {
                "or": [
                  "N",
                  "S",
                  "E",
                  "W"
                ]
              }
            ]
          },
          "post": {
            "not": "entranceArea"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leaveEntranceWithoutCart"
    }
  }
]
